def _calculate_fingerprint(self, X: Sequence[str | Mol]) -> np.ndarray | csr_array:
    X = ensure_mols(X)
    shingles = [self._get_shingles(mol) for mol in X]

    if self.variant == "minhash":
        X = self._minhash_shingles(shingles)
    else:
        X = self._fold_shingles(shingles)

    return csr_array(X) if self.sparse else np.array(X)

def _get_shingles(self, mol: Mol) -> set[str]:
    # atom pair shingles, i.e. the string features of the molecule, which are
    # then hashed (MinHash sketch) or folded (binary and count variants)
    atoms_envs = self._get_atom_envs(mol)
    return self._get_atom_pair_shingles(mol, atoms_envs)

def _minhash_shingles(self, shingles: list[set[str]]) -> np.ndarray:
    from rdkit.Chem.rdMHFPFingerprint import MHFPEncoder

    # MinHash sketch of raw hash values, following the original MAP4 and MAPC
    # implementations; MinHash permutations depend only on fp_size and
    # random_state, so that fingerprints computed in separate calls, batches
    # or parallel jobs use the same hash functions and stay comparable
    encoder = MHFPEncoder(self.fp_size, self._get_minhash_seed())

    # MinHash is invariant to the order of shingles, since it takes minima
    # over the permuted hash values
    return np.array(
        [encoder.FromStringArray(list(mol_shingles)) for mol_shingles in shingles],
        dtype=np.uint32,
    )

def _fold_shingles(self, shingles: list[set[str]]) -> np.ndarray:
    # fold shingle hashes into fp_size buckets with modulo operation
    count = self.variant == "count"
    X = np.zeros(
        (len(shingles), self.fp_size), dtype=np.uint32 if count else np.uint8
    )
    for idx, mol_shingles in enumerate(shingles):
        for shingle in mol_shingles:
            hashed = struct.unpack(
                "<I", sha256(shingle.encode("utf-8")).digest()[:4]
            )[0]
            if count:
                X[idx, hashed % self.fp_size] += 1
            else:
                X[idx, hashed % self.fp_size] = 1
    return X

def _get_minhash_seed(self) -> int:
    # turn random_state into a MinHash seed, deterministically and without
    # consuming the user random stream, since fingerprints are only mutually
    # comparable if they use the same MinHash permutations
    random_state = self.random_state
    if random_state is None:
        return 0
    elif isinstance(random_state, np.random.RandomState):
        return int(deepcopy(random_state).randint(2**32, dtype=np.uint32))
    elif isinstance(random_state, np.random.Generator):
        return int(deepcopy(random_state).integers(2**32, dtype=np.uint32))
    else:
        return int(random_state) % 2**32

