def _add_cip_label(smiles: str, cip_label: str) -> str:
    # replace the symbol of the root (chiral) atom of the rooted SMILES with
    # its CIP descriptor, surrounded by "$" characters, e.g. "C(C)(N)C=O"
    # with CIP label "S" results in "$S$(C)(N)C=O"
    if smiles.startswith("["):
        bracket_end = smiles.find("]")
        rest = smiles[bracket_end + 1 :] if bracket_end != -1 else ""
    elif smiles[:2] in {"Cl", "Br"}:
        rest = smiles[2:]
    else:
        rest = smiles[1:]

    return f"${cip_label}${rest}"

