def _get_atom_envs(self, mol: Mol) -> dict[int, list[str]]:
    from rdkit.Chem import FindMolChiralCenters

    # build the atom environment labels for each radius.
    atom_envs: dict[int, list[str]] = defaultdict(list)

    for atom in mol.GetAtoms():
        atom_idx = atom.GetIdx()
        for radius in range(1, self.radius + 1):
            atom_env = self._find_env(mol, atom_idx, radius)
            atom_envs[atom_idx].append(atom_env)

    if self.include_chirality:
        # MAPC encodes chirality only at the maximal radius, by replacing the
        # symbol of the chiral atom with its CIP descriptor, so that the impact
        # of stereochemistry scales with the molecule size
        chiral_centers = FindMolChiralCenters(
            mol, includeUnassigned=True, useLegacyImplementation=False
        )
        for atom_idx, cip_label in chiral_centers:
            max_radius_smiles = atom_envs[atom_idx][-1] if atom_envs[atom_idx] else ""
            if max_radius_smiles:
                atom_envs[atom_idx][-1] = self._add_cip_label(
                    max_radius_smiles, cip_label
                )

    return atom_envs

def _find_env(self, mol: Mol, atom_identifier: int, radius: int) -> str:
    # build the local environment string at the requested radius
    atom_identifiers_within_radius: list[int] = FindAtomEnvironmentOfRadiusN(
        mol=mol, radius=radius, rootedAtAtom=atom_identifier
    )
    atom_map: dict = {}

    sub_molecule: Mol = PathToSubmol(
        mol, atom_identifiers_within_radius, atomMap=atom_map
    )
    if atom_identifier not in atom_map:
        return ""

    smiles = MolToSmiles(
        sub_molecule,
        rootedAtAtom=atom_map[atom_identifier],
        isomericSmiles=self.include_chirality,
        canonical=True,
    )

    if self.include_chirality:
        # MAPC removes tetrahedral chirality markers ("@" and "@@") from the
        # circular substructure SMILES, keeping E/Z isomerism ("/" and "\")
        smiles = smiles.replace("@", "")

    return smiles

